// Embedded WAVs preserve the offline file:// launcher.
(function(){
 'use strict';
 const encoded=["", "", "", "", "", ""];
 window.VinylFoley={async buffers(context){return Promise.all(encoded.map(value=>{const bytes=Uint8Array.from(atob(value),c=>c.charCodeAt(0));return context.decodeAudioData(bytes.buffer);}));}};
})();
